const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const memphisPoint = ee.Geometry.Point([-90.05, 35.15]); // Near Memphis, TN
  const bufferDistance = 20000; // 20 km buffer to cover a good section of the river
  const geometry = memphisPoint.buffer(bufferDistance);

  const date1_start = '2019-02-01';
  const date1_end = '2019-02-28';

  const date2_start = '2014-02-01';
  const date2_end = '2014-02-28';

  const scale = 1000; // Resolution for calculation (JRC is 30m, but for area comparison, 1km is sufficient and faster)

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('JRC/GSW1_4/MonthlyHistory');

  // Filter for 2019 data
  const img2019 = collection
    .filterDate(date1_start, date1_end)
    .filterBounds(geometry)
    .first(); // Should be only one image for the month

  // Filter for 2014 data
  const img2014 = collection
    .filterDate(date2_start, date2_end)
    .filterBounds(geometry)
    .first(); // Should be only one image for the month

  if (!img2019) {
    console.log(`No JRC Monthly History image found for February 2019 within the geometry.`);
    console.log('C1');
    return;
  }
  if (!img2014) {
    console.log(`No JRC Monthly History image found for February 2014 within the geometry.`);
    console.log('C1');
    return;
  }

  // 3. Processing: Calculate water area
  // The 'water' band contains values indicating water presence:
  // 0: No water
  // 1: Seasonal water
  // 2: Permanent water
  // 3: New permanent water
  // We consider any pixel with 'water' > 0 as surface water.

  // Create a binary water mask (1 for water, 0 for no water)
  const waterMask2019 = img2019.select('water').gt(0);
  const waterMask2014 = img2014.select('water').gt(0);

  // Calculate the area of each pixel at the given scale
  const pixelArea = ee.Image.pixelArea().mask(waterMask2019); // Use one mask for pixel area to apply to both calculations

  // Function to calculate water area
  const calculateWaterArea = (imageMask) => {
    // Multiply the water mask by pixel area to get area in square meters for water pixels
    const waterAreaImage = imageMask.multiply(pixelArea);

    // Sum the water areas within the geometry
    return waterAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    });
  };

  const waterAreaDict2019 = await calculateWaterArea(waterMask2019).getInfo();
  const waterAreaDict2014 = await calculateWaterArea(waterMask2014).getInfo();

  const area_2019_sqm = waterAreaDict2019 ? waterAreaDict2019['water'] : null;
  const area_2014_sqm = waterAreaDict2014 ? waterAreaDict2014['water'] : null;

  // Convert to square kilometers for readability
  const area_2019_sqkm = area_2019_sqm !== null ? area_2019_sqm / 1e6 : null;
  const area_2014_sqkm = area_2014_sqm !== null ? area_2014_sqm / 1e6 : null;

  // Check for C2 (No Valid Pixels)
  if (area_2019_sqkm === 0 && area_2014_sqkm === 0) {
    console.log("No valid water pixels found for either period after masking.");
    console.log('C2');
    return;
  }

  // Check for C3 (Calculation Failure)
  if (area_2019_sqkm === null || area_2014_sqkm === null) {
    console.log(`Calculation failed. 2019 Area: ${area_2019_sqkm}, 2014 Area: ${area_2014_sqkm}`);
    console.log('C3');
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Water extent (Feb 2019): ${area_2019_sqkm.toFixed(2)} sq. km`);
  console.log(`Water extent (Feb 2014): ${area_2014_sqkm.toFixed(2)} sq. km`);

  if (area_2019_sqkm > area_2014_sqkm) {
    console.log('A'); // Yes, higher in 2019
  } else {
    console.log('B'); // No, not higher in 2019
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
